DO $$
DECLARE r RECORD; n BIGINT; nn BIGINT; mm BIGINT;
BEGIN
  CREATE TEMP TABLE IF NOT EXISTS dead_col_probe(tbl text, col text, rows bigint, non_null bigint, meaningful bigint) ON COMMIT DROP;
  DELETE FROM dead_col_probe;
  FOR r IN
    SELECT c.tbl, c.col
    FROM (VALUES ('activity_log','description'),('activity_log','user_name'),('approval_decisions','decided_at'),('approval_decisions','decision'),('audit_logs','action'),('audit_logs','entity_id'),('audit_logs','entity_type'),('autopilot_alerts','alert_type'),('autopilot_alerts','body'),('autopilot_alerts','severity'),('badges','badge_icon'),('badges','badge_name'),('badges','badge_type'),('badges','description'),('badges','earned_at'),('badges','points'),('badges','project_id'),('bid_package_invites','bid_package_items'),('bid_package_invites','bid_packages'),('bid_package_invites','projects'),('bid_package_invites','token'),('bids','amount'),('bids','bidder_company'),('bids','project_id'),('bids','score'),('bids','status'),('bids','submitted_at'),('bids','trade'),('catalog_items','category'),('catalog_items','description'),('catalog_items','name'),('catalog_items','sku_hint'),('catalog_items','unit'),('catalog_items','vertical'),('catalog_vendor_prices','as_of'),('catalog_vendor_prices','catalog_vendors'),('catalog_vendor_prices','item_id'),('catalog_vendor_prices','kind'),('catalog_vendor_prices','lead_time_days'),('catalog_vendor_prices','price'),('catalog_vendor_prices','qty_in_stock'),('catalog_vendor_prices','source'),('catalog_vendor_prices','stock_status'),('catalog_vendor_prices','unit'),('catalog_vendors','is_national'),('catalog_vendors','kind'),('catalog_vendors','name'),('catalog_vendors','verticals'),('catalog_vendors','website'),('cost_reports','notes'),('crew_assignments','worker_id'),('design_addon_subscriptions','status'),('design_addon_subscriptions','white_label_enabled'),('discovery_questions','options'),('document_signature_requests','document_signatures'),('drawing_review_links','expires_at'),('drawing_review_links','token'),('drawing_sheets','file_type'),('drawing_sheets','file_url'),('drawing_sheets','project_id'),('drawing_sheets','sheet_number'),('drawing_sheets','sheet_title'),('fleet_integrations','active'),('franchise_verifications','status'),('franchise_verifications','title'),('franchise_verifications','verified_at'),('generated_documents','data_snapshot'),('generated_documents','doc_type'),('generated_documents','pdf_url'),('generated_documents','project_id'),('generated_documents','source_id'),('generated_documents','source_type'),('generated_documents','status'),('generated_documents','title'),('insurance_certificates','carrier'),('insurance_certificates','expiry_date'),('insurance_certificates','policy_type'),('insurance_certificates','project_id'),('insurance_certificates','status'),('insurance_certificates','sub_id'),('insurance_certificates','sub_name'),('leaderboards','category'),('leaderboards','entity_id'),('leaderboards','entity_name'),('leaderboards','entity_type'),('leaderboards','period'),('leaderboards','project_id'),('leaderboards','rank'),('leaderboards','score'),('lien_waivers','blocks_payment'),('lien_waivers','claimant_name'),('lien_waivers','company_name'),('lien_waivers','subcontractor_id'),('platform_integrations','enabled'),('portal_client_sessions','token'),('portal_payments','amount'),('portal_payments','paid_at'),('portal_sub_sessions','token'),('presence_sessions','page_path'),('project_subcontractors','contract_amount'),('project_subcontractors','email'),('project_subcontractors','is_compliant'),('project_subcontractors','project_id'),('project_subcontractors','status'),('project_subcontractors','subcontractor_id'),('project_subcontractors','subcontractors'),('project_subcontractors','trade'),('project_team','company'),('project_team','role'),('radio_guest_links','expires_at'),('radio_guest_links','name'),('radio_guest_links','project_id'),('radio_guest_links','radio_channels'),('radio_guest_links','token'),('radio_messages','present_at_send'),('radio_messages','transcript'),('resource_forecast','notes'),('roi_configs','electricity_kwh'),('roi_configs','gas_therm'),('sage_activity_log','action_type'),('sage_activity_log','actor'),('sage_activity_log','detail'),('sage_activity_log','rule_id'),('sage_activity_log','summary'),('schedule_phases','end_date'),('schedule_phases','name'),('schedule_phases','percent_complete'),('schedule_phases','start_date'),('subcontractor_insurance','projects'),('subcontractor_insurance','subcontractors'),('team_invites','email'),('team_invites','role'),('team_invites','token'),('tenants','company_name'),('trade_win_factors','avg_over_winner_pct'),('trade_win_factors','confidence'),('trade_win_factors','csi_division'),('trade_win_factors','loss_count'),('trade_win_factors','sample_count'),('trade_win_factors','suggested_multiplier'),('trade_win_factors','trade'),('trade_win_factors','win_count'),('trade_win_factors','win_rate'),('user_badges','badge_icon'),('user_badges','badges'),('user_badges','category'),('user_badges','description'),('users','email'),('w9_requests','projects'),('wage_determinations','base_rate'),('wage_determinations','classification'),('wage_determinations','county'),('wage_determinations','determination_number'),('wage_determinations','effective_date'),('wage_determinations','fringe_rate'),('wage_determinations','state'),('work_assignments','name'),('work_assignments','note'),('work_assignments','projects'),('work_assignments','role'),('work_assignments','scope')) AS c(tbl, col)
    JOIN information_schema.columns ic
      ON ic.table_schema='public' AND ic.table_name=c.tbl AND ic.column_name=c.col
  LOOP
    EXECUTE format(
      'SELECT count(*), count(%I), count(*) FILTER (WHERE %I::text NOT IN (''0'',''false'','''',''0.00'')) FROM %I',
      r.col, r.col, r.tbl) INTO n, nn, mm;
    INSERT INTO dead_col_probe VALUES (r.tbl, r.col, n, nn, mm);
  END LOOP;
END $$;

SELECT tbl, col, rows, non_null, meaningful
FROM dead_col_probe
WHERE rows > 0 AND meaningful = 0
ORDER BY rows DESC, tbl, col;
